-- Member discounts become a percentage per tier per SERVICE CATEGORY (replacing the one percentage per tier).
-- Generated by `prisma migrate diff`; the section after the marker is hand-written.

-- The one-percentage-per-tier column is being REPLACED. If anyone has already set one, stop here rather than
-- silently throw their number away: move it into the new per-category table by hand first.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM "MembershipPlan" WHERE "discountPercent" <> 0) THEN
    RAISE EXCEPTION 'MembershipPlan.discountPercent is set on at least one tier; record it as per-category discounts before migrating';
  END IF;
END $$;

